INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0009-000000000001', 'b0000001-0000-0000-0000-000000000009', 'b0000000-0000-0000-0000-000000000001', 1, 'medios-de-transporte', '{"es": "Medios de Transporte", "en": "Means of Transportation"}'::jsonb, '{"es": "Aprende el vocabulario de los medios de transporte y cómo usar la estructura by + transporte.", "en": "Learn transportation vocabulary and how to use the structure by + transportation."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "En esta lección vas a aprender el vocabulario de los medios de transporte en inglés y la estructura ''by + transporte'' para decir cómo te desplazas de un lugar a otro.", "sections": [{"type": "table", "title": "MEDIOS DE TRANSPORTE", "headers": ["Inglés", "Español"], "rows": [["bus", "autobús"], ["train", "tren"], ["car", "coche"], ["bike / bicycle", "bicicleta"], ["plane", "avión"], ["taxi", "taxi"], ["subway / underground", "metro"], ["on foot", "a pie / caminando"]]}, {"type": "explanation", "title": "BY + TRANSPORTE", "text": "Para decir cómo viajamos usamos ''by + medio de transporte'': ''by bus'', ''by car'', ''by train'', ''by plane'', ''by bike'', ''by taxi'', ''by subway''. Estas expresiones no llevan artículo (no decimos ''by the bus''). La única excepción es ''on foot'' (a pie), que no usa ''by'' sino ''on''."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I go to work by bus.", "es": "Voy al trabajo en autobús."}, {"en": "She travels by train every weekend.", "es": "Ella viaja en tren cada fin de semana."}, {"en": "We go to school by car.", "es": "Vamos a la escuela en coche."}, {"en": "He walks to school on foot.", "es": "Él va a la escuela a pie."}, {"en": "They go to work by bike.", "es": "Ellos van al trabajo en bicicleta."}]}, {"type": "note", "variant": "tip", "text": "Recuerda: usamos ''by'' con casi todos los medios de transporte (by bus, by car, by train), pero ''on foot'' es la excepción — nunca digas ''by foot''."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0009-0001-000000000001', 'b0000002-0000-0000-0009-000000000001', 1, 'flashcard', '{"text": "bus"}'::jsonb, '{"text": "el autobús", "phonetic": "/bʌs/"}'::jsonb, NULL, NULL, '{"vocab:transportation"}'),
('b0000003-0001-0009-0002-000000000001', 'b0000002-0000-0000-0009-000000000001', 2, 'flashcard', '{"text": "train"}'::jsonb, '{"text": "el tren", "phonetic": "/treɪn/"}'::jsonb, NULL, NULL, '{"vocab:transportation"}'),
('b0000003-0001-0009-0003-000000000001', 'b0000002-0000-0000-0009-000000000001', 3, 'flashcard', '{"text": "bicycle"}'::jsonb, '{"text": "la bicicleta", "phonetic": "/ˈbaɪsɪkəl/"}'::jsonb, NULL, NULL, '{"vocab:transportation"}'),
('b0000003-0001-0009-0004-000000000001', 'b0000002-0000-0000-0009-000000000001', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "car", "es": "el coche"}, {"en": "plane", "es": "el avión"}, {"en": "taxi", "es": "el taxi"}, {"en": "subway", "es": "el metro"}]}'::jsonb, NULL, NULL, '{"vocab:transportation"}'),
('b0000003-0001-0009-0005-000000000001', 'b0000002-0000-0000-0009-000000000001', 5, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "bus", "es": "el autobús"}, {"en": "train", "es": "el tren"}, {"en": "bicycle", "es": "la bicicleta"}, {"en": "on foot", "es": "a pie"}]}'::jsonb, NULL, NULL, '{"vocab:transportation"}'),
('b0000003-0001-0009-0006-000000000001', 'b0000002-0000-0000-0009-000000000001', 6, 'multiple_choice', '{"text": "How do you say ''a pie'' in English?"}'::jsonb, '{"text": "on foot"}'::jsonb, '["by foot", "in foot", "with foot"]'::jsonb, '{"es": "''On foot'' es la expresión correcta; nunca decimos ''by foot''."}'::jsonb, '{"vocab:transportation"}'),
('b0000003-0001-0009-0007-000000000001', 'b0000002-0000-0000-0009-000000000001', 7, 'fill_blank', '{"text": "I go to work ___ bus."}'::jsonb, '{"text": "by", "accepted": ["by"]}'::jsonb, NULL, '{"es": "Usamos ''by'' antes de un medio de transporte: ''by bus''."}'::jsonb, '{"grammar:by_transportation","vocab:transportation"}'),
('b0000003-0001-0009-0008-000000000001', 'b0000002-0000-0000-0009-000000000001', 8, 'fill_blank', '{"text": "She goes to school ___ foot."}'::jsonb, '{"text": "on", "accepted": ["on"]}'::jsonb, NULL, '{"es": "''On foot'' es la única expresión de transporte que no usa ''by''."}'::jsonb, '{"grammar:by_transportation","vocab:transportation"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0009-000000000002', 'b0000001-0000-0000-0000-000000000009', 'b0000000-0000-0000-0000-000000000001', 2, 'pedir-y-dar-direcciones', '{"es": "Pedir y Dar Direcciones", "en": "Asking for and Giving Directions"}'::jsonb, '{"es": "Aprende frases para pedir direcciones educadamente y para explicar cómo llegar a un lugar.", "en": "Learn phrases to politely ask for directions and to explain how to get somewhere."}'::jsonb, 'mixed', 22, 13, '{"intro": "En esta lección vas a aprender frases útiles para pedir direcciones en la calle y para explicar a otra persona cómo llegar a un lugar, usando también preposiciones de lugar que ya conoces.", "sections": [{"type": "explanation", "title": "PEDIR DIRECCIONES", "text": "Para pedir direcciones educadamente empezamos con ''Excuse me'' (disculpe). La pregunta más común es ''Excuse me, how do I get to...?'' (Disculpe, ¿cómo llego a...?). También podemos preguntar ''Is there a bank near here?'' (¿Hay un banco cerca de aquí?)."}, {"type": "table", "title": "FRASES PARA DAR DIRECCIONES", "headers": ["Inglés", "Español"], "rows": [["Turn left / right", "Gira a la izquierda / derecha"], ["Go straight ahead", "Sigue todo recto"], ["It''s at the corner", "Está en la esquina"], ["It''s on the left / right", "Está a la izquierda / derecha"], ["It''s next to the bank", "Está al lado del banco"], ["It''s across from the park", "Está enfrente del parque"], ["It''s between the shop and the café", "Está entre la tienda y el café"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "Excuse me, how do I get to the station?", "es": "Disculpe, ¿cómo llego a la estación?"}, {"en": "Go straight ahead and turn left at the corner.", "es": "Sigue todo recto y gira a la izquierda en la esquina."}, {"en": "The museum is across from the park.", "es": "El museo está enfrente del parque."}, {"en": "The bank is next to the supermarket.", "es": "El banco está al lado del supermercado."}]}, {"type": "note", "variant": "tip", "text": "Puedes combinar ''turn left/right'' y ''go straight ahead'' con las preposiciones de lugar que ya conoces (next to, between, across from) para dar direcciones completas."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0009-0001-000000000001', 'b0000002-0000-0000-0009-000000000002', 1, 'multiple_choice', '{"text": "How do you politely start a question to ask for directions?"}'::jsonb, '{"text": "Excuse me, how do I get to...?"}'::jsonb, '["Hello, where is...?", "Please, what is...?", "Sorry, when is...?"]'::jsonb, '{"es": "''Excuse me'' es la forma educada de llamar la atención de alguien antes de preguntar."}'::jsonb, '{"vocab:directions"}'),
('b0000003-0002-0009-0002-000000000001', 'b0000002-0000-0000-0009-000000000002', 2, 'multiple_choice', '{"text": "What does ''Turn left'' mean?"}'::jsonb, '{"text": "Gira a la izquierda"}'::jsonb, '["Sigue todo recto", "Gira a la derecha", "Está en la esquina"]'::jsonb, NULL, '{"vocab:directions"}'),
('b0000003-0002-0009-0003-000000000001', 'b0000002-0000-0000-0009-000000000002', 3, 'fill_blank', '{"text": "___ straight ahead and then turn right."}'::jsonb, '{"text": "Go", "accepted": ["Go", "go"]}'::jsonb, NULL, '{"es": "''Go straight ahead'' significa ''sigue todo recto''."}'::jsonb, '{"vocab:directions"}'),
('b0000003-0002-0009-0004-000000000001', 'b0000002-0000-0000-0009-000000000002', 4, 'fill_blank', '{"text": "The bank is ___ the corner."}'::jsonb, '{"text": "at", "accepted": ["at"]}'::jsonb, NULL, '{"es": "Usamos ''at the corner'' para decir ''en la esquina''."}'::jsonb, '{"vocab:directions"}'),
('b0000003-0002-0009-0005-000000000001', 'b0000002-0000-0000-0009-000000000002', 5, 'translation', '{"text": "Disculpe, ¿cómo llego a la estación?"}'::jsonb, '{"text": "Excuse me, how do I get to the station?", "accepted": ["Excuse me, how do I get to the station?"]}'::jsonb, NULL, NULL, '{"vocab:directions"}'),
('b0000003-0002-0009-0006-000000000001', 'b0000002-0000-0000-0009-000000000002', 6, 'translation', '{"text": "Gire a la izquierda en el semáforo."}'::jsonb, '{"text": "Turn left at the traffic light.", "accepted": ["Turn left at the traffic light."]}'::jsonb, NULL, NULL, '{"vocab:directions"}'),
('b0000003-0002-0009-0007-000000000001', 'b0000002-0000-0000-0009-000000000002', 7, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "Excuse me, how do I get to the museum?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Thank you very much."}]}'::jsonb, '{"text": "Go straight ahead and turn left. It''s next to the bank."}'::jsonb, '["I don''t like museums.", "It''s a very old building.", "The bus is number six."]'::jsonb, NULL, '{"vocab:directions"}'),
('b0000003-0002-0009-0008-000000000001', 'b0000002-0000-0000-0009-000000000002', 8, 'multiple_choice', '{"text": "What does ''It''s on the right'' mean?"}'::jsonb, '{"text": "Está a la derecha"}'::jsonb, '["Está a la izquierda", "Está todo recto", "Está detrás"]'::jsonb, NULL, '{"vocab:directions"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0009-000000000003', 'b0000001-0000-0000-0000-000000000009', 'b0000000-0000-0000-0000-000000000001', 3, 'preposiciones-de-movimiento', '{"es": "Preposiciones de Movimiento", "en": "Prepositions of Movement"}'::jsonb, '{"es": "Aprende a usar to, from, into, onto, across y through para describir movimiento y dirección.", "en": "Learn to use to, from, into, onto, across, and through to describe movement and direction."}'::jsonb, 'grammar', 24, 14, '{"intro": "Ya conoces las preposiciones de lugar (in, on, under, next to...) que describen dónde está algo sin moverse. Ahora vas a aprender las preposiciones de movimiento, que describen hacia dónde se mueve algo o alguien.", "sections": [{"type": "table", "title": "PREPOSICIONES DE MOVIMIENTO", "headers": ["Inglés", "Español", "Ejemplo"], "rows": [["to", "a / hacia", "She goes to the station."], ["from", "desde / de", "He comes from work at six."], ["into", "hacia dentro de", "They walk into the store."], ["onto", "hacia encima de / a bordo de", "He gets onto the bus."], ["across", "a través de / cruzando", "She walks across the street."], ["through", "a través de / por dentro de", "The car drives through the tunnel."]]}, {"type": "explanation", "title": "LUGAR VS. MOVIMIENTO", "text": "Las preposiciones de lugar como ''in'', ''on'' y ''at'' describen una posición fija: ''The car is in the garage'' (el coche está en el garaje, sin moverse). Las preposiciones de movimiento como ''to'', ''into'', ''onto'', ''across'' y ''through'' describen una acción de ir de un lugar a otro: ''The car goes into the garage'' (el coche entra en el garaje, en movimiento). Usa un verbo de movimiento (go, walk, drive, get) junto con estas preposiciones."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "She walks to the station every day.", "es": "Ella camina a la estación todos los días."}, {"en": "He comes from work at six.", "es": "Él viene del trabajo a las seis."}, {"en": "They walk into the store.", "es": "Ellos entran en la tienda."}, {"en": "He gets onto the bus quickly.", "es": "Él sube al autobús rápidamente."}, {"en": "She walks across the street.", "es": "Ella cruza la calle."}, {"en": "The car drives through the tunnel.", "es": "El coche pasa por el túnel."}]}, {"type": "note", "variant": "tip", "text": "Truco: si la oración describe una acción de moverse de un lugar a otro, usa una preposición de movimiento (to, into, onto, across, through); si describe una posición fija, usa una preposición de lugar (in, on, at)."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0009-0001-000000000001', 'b0000002-0000-0000-0009-000000000003', 1, 'multiple_choice', '{"text": "She walks ___ the park every morning."}'::jsonb, '{"text": "through"}'::jsonb, '["in", "at", "on"]'::jsonb, '{"es": "''Through'' describe movimiento de un lado al otro por dentro de un lugar."}'::jsonb, '{"grammar:prepositions_of_movement"}'),
('b0000003-0003-0009-0002-000000000001', 'b0000002-0000-0000-0009-000000000003', 2, 'multiple_choice', '{"text": "How do you say ''subir al autobús'' in English?"}'::jsonb, '{"text": "get onto the bus"}'::jsonb, '["get in the bus", "get at the bus", "get from the bus"]'::jsonb, '{"es": "Usamos ''onto'' para describir el movimiento de subir a un vehículo o superficie."}'::jsonb, '{"grammar:prepositions_of_movement","vocab:transportation"}'),
('b0000003-0003-0009-0003-000000000001', 'b0000002-0000-0000-0009-000000000003', 3, 'fill_blank', '{"text": "He comes ___ work at six."}'::jsonb, '{"text": "from", "accepted": ["from"]}'::jsonb, NULL, '{"es": "''From'' indica el origen o punto de partida del movimiento."}'::jsonb, '{"grammar:prepositions_of_movement"}'),
('b0000003-0003-0009-0004-000000000001', 'b0000002-0000-0000-0009-000000000003', 4, 'fill_blank', '{"text": "They walked ___ the street to the shop."}'::jsonb, '{"text": "across", "accepted": ["across"]}'::jsonb, NULL, '{"es": "''Across'' indica movimiento de un lado al otro de algo, como una calle."}'::jsonb, '{"grammar:prepositions_of_movement"}'),
('b0000003-0003-0009-0005-000000000001', 'b0000002-0000-0000-0009-000000000003', 5, 'fill_blank', '{"text": "The car drove ___ the tunnel."}'::jsonb, '{"text": "through", "accepted": ["through"]}'::jsonb, NULL, '{"es": "''Through'' indica movimiento por dentro de un espacio, como un túnel."}'::jsonb, '{"grammar:prepositions_of_movement"}'),
('b0000003-0003-0009-0006-000000000001', 'b0000002-0000-0000-0009-000000000003', 6, 'translation', '{"text": "Ella entra en la tienda."}'::jsonb, '{"text": "She walks into the store.", "accepted": ["She walks into the store.", "She goes into the store."]}'::jsonb, NULL, NULL, '{"grammar:prepositions_of_movement"}'),
('b0000003-0003-0009-0007-000000000001', 'b0000002-0000-0000-0009-000000000003', 7, 'translation', '{"text": "El tren va de Madrid a Barcelona."}'::jsonb, '{"text": "The train goes from Madrid to Barcelona.", "accepted": ["The train goes from Madrid to Barcelona."]}'::jsonb, NULL, NULL, '{"grammar:prepositions_of_movement","vocab:transportation"}'),
('b0000003-0003-0009-0008-000000000001', 'b0000002-0000-0000-0009-000000000003', 8, 'word_bank_fill', '{"text": "He gets ___ the train and travels ___ the city."}'::jsonb, '{"answers": ["onto", "through"]}'::jsonb, '["into", "across"]'::jsonb, '{"es": "Sube al (onto) tren y viaja a través de (through) la ciudad."}'::jsonb, '{"grammar:prepositions_of_movement","vocab:transportation"}');
